-- Brewhouse: online coffee shop. Generated by generate_brewhouse.py (seeded).
CREATE TABLE customers (
  customer_id int PRIMARY KEY, first_name text NOT NULL, last_name text NOT NULL, email text,
  city text, country text, signup_date date NOT NULL);
CREATE TABLE products (
  product_id int PRIMARY KEY, name text NOT NULL, category text NOT NULL, price numeric(7,2) NOT NULL,
  cost numeric(7,2) NOT NULL, is_active boolean NOT NULL DEFAULT true, attributes jsonb);
CREATE TABLE orders (
  order_id int PRIMARY KEY, customer_id int NOT NULL REFERENCES customers, order_date timestamp NOT NULL,
  status text NOT NULL, channel text NOT NULL);
CREATE TABLE order_items (
  order_item_id int PRIMARY KEY, order_id int NOT NULL REFERENCES orders, product_id int NOT NULL REFERENCES products,
  quantity int NOT NULL, unit_price numeric(7,2) NOT NULL);
CREATE TABLE employees (
  employee_id int PRIMARY KEY, first_name text NOT NULL, last_name text NOT NULL, role text NOT NULL, department text NOT NULL,
  salary int NOT NULL, hire_date date NOT NULL, manager_id int REFERENCES employees);
CREATE TABLE price_bands (band_id int PRIMARY KEY, band_name text NOT NULL, min_price numeric NOT NULL, max_price numeric NOT NULL);
CREATE TABLE product_stock (product_id int PRIMARY KEY REFERENCES products, quantity int NOT NULL);
CREATE TABLE staging_stock (product_id int, quantity int);
CREATE TABLE loyalty_accounts (customer_id int PRIMARY KEY REFERENCES customers, points int NOT NULL);
CREATE TABLE customer_imports (import_id int PRIMARY KEY, email text, first_name text, last_name text, city text);
CREATE TABLE orders_flat (order_id int, order_date date, customer_name text, customer_email text, product_name text, category text, price numeric(7,2), quantity int);
CREATE TABLE events_log (event_id int PRIMARY KEY, logged_at timestamp NOT NULL, customer_id int, page text NOT NULL, session_token text NOT NULL);














